"""Unit-conversion parentheses, as a negative signal.

Component L15 MLP down_proj #3589 is mostly quiet, but it swings hard negative when the
text is about to restate a measurement in other units, as in "20 kilometres (12 miles)",
"0 °C (32 °F)" or "1 cm (0.4 in)". The strongest value sits on the opening parenthesis
right after a unit and on the first digits of the restated number, then decays over the
next few tokens. Its output pushes the next-token distribution toward "translated /
converted / equivalent" words, so the activation is negative where such a restatement starts.

This program reproduces that profile from the last few tokens only:
  - "(" directly after a length or mass unit: -48 for metric-scale units (km, metres, cm,
    °C), -16 for the others (miles, feet, inches, m, kg, ...), then the value decays over the
    next five tokens inside the parenthesis;
  - any other "(": a small negative, -1;
  - a quote or colon right after "means", "meaning", "translation", "English", or a language
    name (a gloss of the word just given): -8 to -28.
Everything else is 0. It explains only part of the variance: the activation is largely
diffuse, and most of the rest is not captured by these cues.
"""
from collections.abc import Mapping

READS = ()

BIG_UNITS = {"km", "kilometres", "kilometers", "metres", "meters", "cm", "°C"}
SMALL_UNITS = {"miles", "feet", "inches", "mi", "m", "kg", "mm", "ft", "lb", "lbs", "pounds",
               "acres", "hectares"}
OPEN = {"(", "（"}
CLOSE = {")", "）"}
# value at the paren (offset 0) and at each following token inside it
PROFILE = [-32.0, -29.0, -17.0, -9.0, -4.0, -2.0]
GLOSS_CUES = {"means": -15.0, "meaning": -15.0, "translation": -28.0, "English": -20.0,
              "Chinese": -10.0, "Spanish": -10.0, "Greek": -8.0, "German": -8.0}
GLOSS_OPENERS = {'"', '("', "“", ":", "(", "（"}
OTHER_PAREN = -1.0


def step(carry, prefix, upstream: Mapping):
    toks = [s.strip() for s in prefix.token_strings[-8:]]
    docs = prefix.document_ids[-8:]
    n = len(toks)
    cur = toks[-1]
    # 1. are we at, or within a few tokens after, an "(" that follows a unit?
    for k in range(min(n, len(PROFILE))):
        i = n - 1 - k
        if docs[i] != docs[-1] or toks[i] in CLOSE:
            break
        if toks[i] in OPEN:
            if i >= 1 and docs[i - 1] == docs[i]:
                if toks[i - 1] in BIG_UNITS:
                    return carry, 1.5 * PROFILE[k]
                if toks[i - 1] in SMALL_UNITS:
                    return carry, 0.5 * PROFILE[k]
            break
    # 2. any other opening parenthesis
    if cur in OPEN:
        return carry, OTHER_PAREN
    # 3. a gloss opener right after a cue word
    if n >= 2 and docs[-2] == docs[-1] and toks[-2] in GLOSS_CUES and cur in GLOSS_OPENERS:
        return carry, GLOSS_CUES[toks[-2]]
    return carry, 0.0

"""Coordination joiners: negative on the words and symbols that join parallel items.

Component p-82af68dd@100000/layers.15.mlp.down_proj:3600 is negative where the text joins
parallel items: "X and Y", "X or Y", "X & Y", "X、Y", "X und Y", and the commas or dashes
of a series "X, Y, Z". Its size depends on what is being joined:

- a joiner directly after a short item (one or two words, or a number) is most negative:
  "1 and 2", "March and November", "material and workmanship", "Uber and Lyft";
- a joiner after a comma (", and" starting a new clause) is only mildly negative;
- commas in a list of numbers or names are moderately negative, and so is the space that
  follows such a comma; commas between clauses are only weakly negative.

The program tracks how many tokens have passed since the last separator (a comma, a joiner,
or a sentence mark), which is the size of the item just before the current token.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

JOINERS = {
    " and", " or", " nor", " &", "&", " und", " et", " oder", " ou", " и",
    "和", "或", "、", "与", "及",
}
DASHES = {"-", " -", "/", " /", "+", " +", "–"}
SEPARATORS = {",", ";", ":", ".", "\n", "!", "?"} | JOINERS


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    item = 0 if carry is None or new_doc else carry  # tokens since the last separator
    short = item <= 2
    if tok in JOINERS:
        if prev == "," or prev == "":
            value = -1.8  # ", and" starting a new clause or item
        elif prev.strip().isdigit():
            value = -8.0 if short else -6.5  # "1 and 2", "March and November"
        elif prev.strip().isalpha():
            value = -8.5 if short else (-5.8 if item <= 6 else -4.4)  # "food and drink"
            if prev.strip()[0].isupper():
                value -= 2.0  # names: "Uber and Lyft", "Health and Human Services"
        else:
            value = -2.0
    elif tok == ",":
        if prev.strip().isdigit():
            value = -4.5 if short else -3.0  # number lists and tuples
        elif short:
            value = -3.0  # commas in a list of short items
        else:
            value = -1.3  # commas between clauses
    elif tok == " " and prev == ",":
        value = -1.8  # the space before a number in a list: "54, 56"
    elif tok in DASHES:
        value = -4.0 if prev.strip().isdigit() else -1.7
    else:
        value = 0.0
    next_item = 0 if tok in SEPARATORS or new_doc else item + 1
    return next_item, value

"""Activation of down_proj component 3601 in layer 15 (MLP unit 3601), predicted by a few concept rules.

What the component is: its activation is almost exactly 0.79 times the value of layer 15's
MLP hidden unit 3601 (silu(gate) * up). It is mostly near zero, but goes strongly negative
(down to about -14) on some tokens. Those tokens sit in the middle or at the end of multi-word
names and titles and technical terms, e.g. "Mississippi [Stud] Poker", "Twenty-First [Century]",
"Making A Difference Loc[ally]". Most of its variance, though, comes from long-range context.

What this program does: it predicts from the text so far, with four rules.
  - a capitalised word right after another capitalised word (inside a name or title): clearly negative;
  - newlines and punctuation: slightly negative;
  - digits: slightly positive;
  - everything else, and the first token of each document: the component's typical value.
It reads only the current and previous token, so it is causal and needs no state.
"""

READS = ()

NAME_PART = -0.3  # capitalised word following a capitalised word: inside a name or title
PUNCTUATION = -0.1  # a newline or punctuation token
DIGIT = 0.07  # a digit
TYPICAL = -0.03  # anything else: the component's mean

PUNCT_CHARS = set(".,;:!?'\"“”‘’《》()[]{}-")


def _is_capitalised(text):
    return text.strip()[:1].isupper()


def _is_punctuation(text):
    core = text.strip()
    return bool(core) and set(core) <= PUNCT_CHARS


def step(carry, prefix, upstream):
    # The first token of a document has no context: its activation is about zero.
    if len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    if _is_capitalised(cur) and _is_capitalised(prev):
        return carry, NAME_PART
    if "\n" in cur or _is_punctuation(cur):
        return carry, PUNCTUATION
    if cur.strip().isdigit():
        return carry, DIGIT
    return carry, TYPICAL

"""Activation of one MLP hidden unit of layer 15 (component 3608 of layers.15.mlp.down_proj).

What it responds to, in plain terms: it is a context-driven unit with little lexical
identity. The clearest pattern is on verbs in running prose: it is strongly positive on a
past participle that follows a form of "be" or "have" ("was found", "were used",
"has been shown"), mildly positive on other participles and on discourse connectives
("however", "therefore", "also"), slightly positive on other verbs, and near zero or
negative on nouns, especially technical nouns in code and documentation.

This program predicts that pattern from the current word and the word before it. It is a
rough description: word classes alone explain about 1% of the variance.
"""

from functools import lru_cache

import wordnet

READS: tuple[str, ...] = ()

AUX = {"be", "is", "are", "was", "were", "been", "being", "am", "has", "have", "had"}
CONNECTIVES = {"however", "therefore", "thus", "also", "although", "since", "because",
               "finally", "moreover", "hence", "furthermore", "indeed"}
IRREGULAR = {"made", "given", "shown", "found", "known", "taken", "seen", "done", "used",
             "built", "written", "set", "run", "led", "held", "based", "left", "kept",
             "begun", "chosen", "read", "driven", "thought", "brought", "lost", "shown"}

BASE, PARTICIPLE_AFTER_AUX, OTHER_PARTICIPLE, VERB, NOUN = 0.1, 1.0, 0.4, 0.15, 0.05


@lru_cache(maxsize=None)
def word_class(word: str) -> str:
    """'verb', 'noun' or '' from WordNet; a noun is a word that is only a noun."""
    if not word.isalpha():
        return ""
    tags = wordnet.parts_of_speech(word)
    if "verb" in tags:
        return "verb"
    if tags == {"noun"}:
        return "noun"
    return ""


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    participle = (word.endswith("ed") and len(word) > 3) or word in IRREGULAR
    if participle and before in AUX:
        value = PARTICIPLE_AFTER_AUX
    elif participle:
        value = OTHER_PARTICIPLE
    elif word in CONNECTIVES:
        value = OTHER_PARTICIPLE
    elif word_class(word) == "verb":
        value = VERB
    elif word_class(word) == "noun":
        value = NOUN
    else:
        value = BASE
    return carry, float(value)

"""Copula-predicate detector for layer 15 MLP unit 3618 (a down_proj component).

What it does: the component is negative inside a "be" predicate, the stretch of text
that says what a subject is, was or is doing. Its activation is
  * most negative on the be-verb itself (is, are, was, were, be, been, am, 're, and
    's after a pronoun, as in "it's"; a possessive 's after a noun is ignored)
    when it follows a subject. The more the subject points back to a topic
    ("This is", "the problem is") the more negative; a pronoun ("it is", "they are")
    is less; a plain noun less again; "What is" / "there is" / "here is" barely at all,
  * negative on adverbs that qualify a predicate: mostly, mainly, especially and
    primarily strongest; only, just, even, typically less; also and not barely,
  * negative for the word right after a be-verb (a, an, the strongest; then a
    preposition such as in, of, to, for) and weakly for the one after that,
  * near zero elsewhere.
The numbers are averages of its activation in each case, rounded, from about 8000
training rows; the program predicts them and has no other state than a short countdown
from the last be-verb.
"""

READS = ()

BE_FORMS = {"is", "are", "was", "were", "be", "been", "being", "am", "'s", "'re", "'m", "’s", "’re", "’m"}
TOPIC_SUBJECTS = {"this", "that", "these", "those", "problem", "question", "issue"}
PRONOUN_SUBJECTS = {"it", "they", "he", "she", "we", "you", "i", "who", "which", "one"}
NO_SUBJECT = {"", "what", "here", "there", "where", "how", "why", "when"}
QUALIFIERS = {
    "mostly": -5.0, "mainly": -5.0, "especially": -5.0, "primarily": -5.0,
    "only": -2.0, "just": -2.0, "even": -1.6, "typically": -2.9,
    "also": -0.6, "not": -0.6,
}
POSSESSIVE_S = {"'s", "’s"}
ARTICLES = {"a", "an", "the"}
PREPOSITIONS = {"in", "on", "of", "to", "for", "as", "with", "from", "by", "at", "both", "all"}
CLAUSE_END = set(".!?;:\n,")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    docs = prefix.document_ids
    same_doc = len(docs) > 1 and docs[-1] == docs[-2]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    since = carry[0] if carry else None
    if not same_doc or word == "" or any(c in CLAUSE_END for c in word):
        since = None
    if word in POSSESSIVE_S and prev not in TOPIC_SUBJECTS | PRONOUN_SUBJECTS | NO_SUBJECT:
        return (None,), 0.0
    if word in BE_FORMS:
        if prev in TOPIC_SUBJECTS:
            value = -3.6
        elif prev in PRONOUN_SUBJECTS:
            value = -2.7
        elif prev in NO_SUBJECT or prev == "":
            value = -0.7
        else:
            value = -1.2
        return (0,), value
    since = None if since is None else since + 1
    if word in QUALIFIERS:
        value = QUALIFIERS[word]
    elif since == 1:
        value = -1.9 if word in ARTICLES else (-1.5 if word in PREPOSITIONS else -0.4)
    elif since == 2:
        value = -0.2
    else:
        value = 0.0
    return (since,), value

"""Delimiter neuron (layer 15, MLP unit feeding the 'name' direction).

It reads the text so far and predicts how strongly this component fires on the newest token.
It mostly marks the seams of lists of knowledge-base triples, such as
"X — relation — Y", "X | relation | Y" or "X -> relation -> Y", one triple per line:
- a bare line break ending such a triple: strongest;
- the first word of the next line when it repeats the previous triple's subject: strong
  (the model is about to copy the subject); a new subject is only mildly raised;
- the few words after such a line start are mildly raised;
- a bare line break ending other prose or a title: moderate; ending a line of code: weak;
- separator punctuation joining list items (quote-comma, arrow, em dash, pipe, double
  underscore): moderate; spaces: weak; other words, digits and tokens: about zero.
"""
import re

READS = ()

SEPARATORS = {'",', "',", ' ->', ' —', ' |', '__', '",\n', "',\n"}
KB_LINE = re.compile(r' — | \| | -> |instance of')
CODE_LINE = re.compile(r'[;{}()=]|\t|^\s{2,}')
SUBJECT_END = re.compile(r' — | \| | -> |,')


def step(carry, prefix, upstream):
    # carry: (text of the current line so far, subject of the previous line if it was a
    # knowledge-base triple else None)
    if carry is None or prefix.position == 0:
        line, subject = '', None
    else:
        line, subject = carry
    tok = prefix.token_strings[-1]
    index = len(line)  # characters of this line before the newest token
    if '\n' in tok:
        kb = KB_LINE.search(line) is not None
        code = CODE_LINE.search(line) is not None
        if tok.strip() == '':
            value = 7.8 if kb else (0.6 if code else 1.5)
        else:
            value = 1.7 if kb else 0.2
        new_subject = SUBJECT_END.split(line.strip(), 1)[0] if kb else None
        return (tok.split('\n')[-1], new_subject), value
    word = tok.strip()
    if index == 0 and subject is not None:
        value = 7.6 if word and subject.startswith(word) else 1.4
    elif subject is not None and index < 12:
        value = 1.1
    elif tok in SEPARATORS:
        value = 2.3
    elif tok.strip() == '':
        value = 0.2
    else:
        value = 0.0
    return (line + tok, subject), value

"""A word detector for formal requests, applications and claims.

Component p-82af68dd@100000/layers.15.mlp.down_proj:3627 writes into the residual stream along
one fixed direction. Its activation is mostly near zero, but it goes strongly negative on words
used in the sense of formally asking for, applying for, claiming, submitting or appealing
something to an authority: "submit", "petition", "claim", "appeal", "filing", "upload", "login",
and the Chinese 申请 (apply), 提交 (submit), 请求 (request). Milder negatives sit on the softer
words "request", "application", "apply", "register", "contact", "send". The same English words
used in a software or electrical sense (apply a function, apply voltage, an HTTP request) tend
to be near zero or slightly positive; the program does not tell the senses apart.

The function word right after such a word ("apply [for]", "appeal [to]", "request [your]") is
also negative. Smaller positive bumps follow instruction phrases ("please", "shall"), and
"of/after/from" right after a time span ("within 30 days of", "within 6 days after").

This is a word-list program with fitted scales. It explains under 1% of the activation's variance
on held-out rows. The large values are spread over many contexts; a full token-to-mean table
would explain about 3%, but it has no concept behind it, so this list is the readable version.
"""

READS = ()

STRONG = {
    "submit", "submitted", "submitting", "submission", "submits", "petition", "petitions",
    "appeal", "appeals", "appealed", "appellate", "filing", "filed", "file", "claim", "claims",
    "complain", "complaint", "complaints", "complained", "upload", "uploaded", "login", "plea",
    "prayer", "申请", "提交", "提出", "上传", "申し込み", "申し", "求", "請求", "请求", "申報",
    "报送", "递交", "投诉", "举报", "报告", "報告",
}
WEAK = {
    "request", "requests", "requested", "requesting", "application", "applications", "apply",
    "applied", "applying", "applicant", "applicants", "register", "registration", "registered",
    "send", "sending", "sent", "contact", "enter", "seek", "seeking", "sought", "deposit", "loan",
    "loans", "permission", "benefit", "benefits", "登録", "注册", "注冊", "貸款", "贷款",
}
FUNCTION_AFTER_REQUEST = {"to", "for", "a", "an", "the", "your", "their", "in"}
TIME_UNITS = {"days", "day", "years", "months", "weeks", "hours"}
FOLLOWS_TIME = {"of", "after", "from"}
INSTRUCTION = {"please", "shall"}

SCALE = {
    "strong": -1.31,  # the request word itself
    "weak": -0.88,
    "strong_then_function": -1.7,  # "apply [for]", "appeal [to]"
    "weak_then_function": -0.87,
    "time": 0.36,
    "instruction": 0.42,
}
BASELINE = -0.045


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    cur = word(prefix.token_strings[-1])
    same_doc = t > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    value = BASELINE
    if cur in STRONG:
        value += SCALE["strong"]
    elif cur in WEAK:
        value += SCALE["weak"]
    if prev in STRONG and cur in FUNCTION_AFTER_REQUEST:
        value += SCALE["strong_then_function"]
    elif prev in WEAK and cur in FUNCTION_AFTER_REQUEST:
        value += SCALE["weak_then_function"]
    if cur in INSTRUCTION:
        value += SCALE["instruction"]
    if prev in TIME_UNITS and cur in FOLLOWS_TIME:
        value += SCALE["time"]
    return carry, float(value)

"""Token-class rule for layers.15.mlp.down_proj:3633 (MLP hidden unit 3633 of layer 15).

Honest summary: this component is a dense, context-driven unit. Its activation is mostly a
small signed background (std about 0.5) with rare large spikes, and no token identity, pair of
tokens, or simple context feature explains more than about 1% of its variance. What the rule
keeps is the coarsest structure found:
  - line breaks are the most positive tokens on average (mean about 0.45, and they account for
    most of the spikes above 3), so they get a positive value;
  - full stops are mildly positive;
  - chat and tool markup (<|im_start|>, <tool_call>, </think>, ...) is negative;
  - everything else sits near the component's mean activation.
It explains only a sliver of the variance; the value of this program is the sign and rough size
of the line-break and markup effects, not a faithful prediction of the spikes.
"""

READS = ()

LINE_BREAK = 0.45
FULL_STOP = 0.2
MARKUP = -0.05
ELSE = 0.05


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok.startswith(("<|", "<think", "</think", "<tool")):
        value = MARKUP
    elif "\n" in tok and tok.strip() == "":
        value = LINE_BREAK
    elif tok == ".":
        value = FULL_STOP
    else:
        value = ELSE
    return carry, float(value)

"""Superlative-anticipation feature (layer 15, MLP hidden unit 3635, read out by down_proj).

What the component is: almost all of its activation is one MLP hidden unit of layer 15
(unit 3635, scaled by its output norm). Read through the unembedding, its positive direction
promotes superlatives ("most", "best", "greatest", "strongest", "hottest", 最强, 史上最 ...).
So it is positive where the text is set up to name a superlative, such as "perhaps [the] most",
"arguably [the] best", "one of [the] greatest", and negative on the superlative itself and on
the words just after it (the head of a superlative phrase, as in "the coolest [place]").

What this program does: a handful of word rules, each with a fitted value. A position gets:
  +0.35 if its word is a hedge that often comes right before a superlative ("arguably",
        "possibly", "perhaps", "probably", ...);
  +0.25 if its word is "the", "of" or "a" right after a quantifier or partitive word ("one of the",
        "some of", "is the", ...);
  -0.17 if its word is itself a superlative;
  -0.19 if a superlative occurred in the three words before it;
  0 otherwise.
The rules are read from the prefix only, within the same document.

Honest limit: these rules explain very little. The component's activation is mostly a diffuse,
context-dependent body (std about 0.5) that no short word list captures; the superlative rules only
catch its tails. A per-token lookup table reaches about 2.5% of variance on the same data, and these
rules about 0.3% to 1%.
"""

READS = ()

HEDGES = {"arguably", "possibly", "perhaps", "probably", "undoubtedly", "sometimes", "maybe", "likely"}
QUANTIFIERS = {"one", "some", "most", "many", "is", "was", "of", "among", "as", "perhaps", "possibly"}
SUPERLATIVES = {
    "most", "best", "greatest", "largest", "biggest", "highest", "finest", "worst", "oldest",
    "toughest", "hottest", "richest", "hardest", "earliest", "poorest", "weakest", "brightest",
    "youngest", "smallest", "lowest", "longest", "tallest", "strongest", "deepest", "coolest",
    "top", "favorite", "favourite",
}


def is_superlative(word):
    return word in SUPERLATIVES or (word.endswith("est") and len(word) > 4)


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings]
    docs = prefix.document_ids
    word = words[-1]
    # the up-to-three words before this one, within the same document
    before = []
    for i in range(len(words) - 2, max(-1, len(words) - 5), -1):
        if docs[i] != docs[-1]:
            break
        before.append(words[i])
    previous = before[0] if before else ""
    if word in HEDGES:
        return carry, 0.35
    if word in ("the", "of", "a") and previous in QUANTIFIERS:
        return carry, 0.25
    if is_superlative(word):
        return carry, -0.17
    if any(is_superlative(w) for w in before):
        return carry, -0.19
    return carry, 0.0
